//! Cell-for-cell parity against Python's two circular-footprint rasterizations.
//!
//! The fixture is generated by `scripts/capture_footprint_fixture.py`, which
//! checks its own recording against a live `CoverageMap` before writing it.
//!
//! Comparison is on the hit sequence **including multiplicity and order**, not
//! on the set of touched cells: coverage counts revisits, so a rasterizer that
//! dropped a repeated hit would still pass a set comparison while quietly
//! changing `mean_revisits`.

use argusnet_mapping::{rasterize_circle, GridBounds, Sampling};
use serde::Deserialize;

#[derive(Deserialize)]
struct Fixture {
    cases: Vec<Case>,
    arange_cases: Vec<ArangeCase>,
}

#[derive(Deserialize)]
struct ArangeCase {
    start: String,
    stop: String,
    step: String,
    values: Vec<String>,
}

#[derive(Deserialize)]
struct Case {
    name: String,
    note: String,
    bounds: Bounds,
    dimensions: [usize; 2],
    center_xy: [String; 2],
    radius_m: String,
    world_anchored: Vec<[usize; 2]>,
    cell_disc: Vec<[usize; 2]>,
}

#[derive(Deserialize)]
struct Bounds {
    x_min_m: String,
    x_max_m: String,
    y_min_m: String,
    y_max_m: String,
    resolution_m: String,
}

/// Floats cross as strings; `str::parse` is exact where `serde_json`'s float
/// parser is off by an ULP, which at a cell boundary is a different cell.
fn f(text: &str) -> f64 {
    text.parse().expect("fixture float")
}

fn load() -> Fixture {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../tests/fixtures/footprint_cells.json"
    );
    let text = std::fs::read_to_string(path).expect("fixture readable");
    serde_json::from_str(&text).expect("fixture parses")
}

fn bounds_of(case: &Case) -> GridBounds {
    GridBounds {
        x_min_m: f(&case.bounds.x_min_m),
        x_max_m: f(&case.bounds.x_max_m),
        y_min_m: f(&case.bounds.y_min_m),
        y_max_m: f(&case.bounds.y_max_m),
        resolution_m: f(&case.bounds.resolution_m),
    }
}

fn check(case: &Case, sampling: Sampling, expected: &[[usize; 2]]) {
    let bounds = bounds_of(case);
    let center = [f(&case.center_xy[0]), f(&case.center_xy[1])];
    let actual = rasterize_circle(&bounds, center, f(&case.radius_m), sampling)
        .unwrap_or_else(|e| panic!("{} / {:?}: {e}", case.name, sampling));
    let expected: Vec<(usize, usize)> = expected.iter().map(|c| (c[0], c[1])).collect();
    assert_eq!(
        actual.len(),
        expected.len(),
        "{} / {:?} ({}): hit count differs",
        case.name,
        sampling,
        case.note
    );
    assert_eq!(
        actual, expected,
        "{} / {:?} ({}): hit sequence differs",
        case.name, sampling, case.note
    );
}

#[test]
fn world_anchored_matches_python_cell_for_cell() {
    for case in load().cases {
        check(&case, Sampling::WorldAnchored, &case.world_anchored);
    }
}

#[test]
fn cell_disc_matches_python_cell_for_cell() {
    for case in load().cases {
        check(&case, Sampling::CellDisc, &case.cell_disc);
    }
}

#[test]
fn grid_dimensions_match_python() {
    for case in load().cases {
        let (nx, ny) = bounds_of(&case).dimensions().expect("valid bounds");
        assert_eq!([nx, ny], case.dimensions, "{}: grid dimensions", case.name);
    }
}

/// The finding this port exists to make visible: the two rasterizations are not
/// interchangeable. If a future change makes them agree everywhere, that is a
/// behaviour change to the simulation and this test should fail rather than
/// let it land silently.
#[test]
fn the_two_samplings_disagree_where_the_radius_is_not_a_whole_number_of_cells() {
    let mut disagreements = 0;
    for case in load().cases {
        let bounds = bounds_of(&case);
        let radius = f(&case.radius_m);
        let ratio = radius / bounds.resolution_m;
        let integral = (ratio - ratio.round()).abs() < 1e-12;

        let mut world = case.world_anchored.clone();
        let mut disc = case.cell_disc.clone();
        world.sort_unstable();
        world.dedup();
        disc.sort_unstable();
        disc.dedup();

        if world != disc {
            disagreements += 1;
            assert!(
                !integral || radius < bounds.resolution_m,
                "{}: samplings disagree at an integral ratio of {ratio}",
                case.name
            );
        }
    }
    assert!(
        disagreements > 0,
        "fixture no longer covers a case where the two rasterizations differ"
    );
}

/// The lattice is `np.arange`, and numpy computes it as `start + i*step` rather
/// than as a running sum. The two agree until `step` is inexact in binary, after
/// which they drift by an ULP or so -- rarely enough to move a sample across a
/// cell boundary, so cell parity alone does not pin it. Compare the values
/// directly, bit for bit.
#[test]
fn lattice_reproduces_numpy_arange_bit_for_bit() {
    for case in load().arange_cases {
        let (start, stop, step) = (f(&case.start), f(&case.stop), f(&case.step));
        let actual = argusnet_mapping::footprint::arange_for_test(start, stop, step);
        let expected: Vec<f64> = case.values.iter().map(|v| f(v)).collect();
        assert_eq!(
            actual.len(),
            expected.len(),
            "arange({start}, {stop}, {step}): length"
        );
        for (index, (a, e)) in actual.iter().zip(&expected).enumerate() {
            assert_eq!(
                a.to_bits(),
                e.to_bits(),
                "arange({start}, {stop}, {step})[{index}]: {a:?} != {e:?}"
            );
        }
    }
}
